    private ImageButton iconButton(int id,String label,Runnable action){ImageButton b=new ImageButton(this);b.setBackground(round(light?0x09000000:0x15ffffff,24,light?0x18000000:0x25ffffff));b.setPadding(dp(9),dp(9),dp(9),dp(9));b.setScaleType(ImageView.ScaleType.CENTER_INSIDE);b.setImageDrawable(vector(id,20));b.setContentDescription(label);b.setOnClickListener(v->action.run());return b;}
    private LinearLayout iconAction(int id,String label,Runnable action){LinearLayout item=vertical();item.setGravity(Gravity.CENTER);item.setClickable(true);item.setFocusable(true);item.setContentDescription(label);item.setOnClickListener(v->action.run());ImageView icon=new ImageView(this);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);icon.setImageDrawable(vector(id,22));item.addView(icon,new LinearLayout.LayoutParams(dp(22),dp(22)));TextView name=text(label,11,fg(),false);name.setIncludeFontPadding(false);name.setGravity(Gravity.CENTER);name.setSingleLine(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(17));lp.topMargin=dp(4);item.addView(name,lp);return item;}
    private FrameLayout.LayoutParams frame(int w,int h,int gravity){return new FrameLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h),gravity);}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
