    private void applyTheme(){root.setBackgroundColor(bg());header.setBackgroundColor(bg());gallery.theme(light);glass.theme(light);if(Build.VERSION.SDK_INT>=30){WindowInsetsController ctl=getWindow().getInsetsController();if(ctl!=null)ctl.setSystemBarsAppearance(light?WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS:0,WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS|WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS);}else getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION|(light?(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR):0));}
    private void buildHeader(){header.removeAllViews();TextView brand=text("H I V E   /   G A L L E R Y",9,muted(),true);brand.setLetterSpacing(.10f);header.addView(brand,new LinearLayout.LayoutParams(-1,dp(18)));
        LinearLayout row=horizontal();header.addView(row,new LinearLayout.LayoutParams(-1,dp(50)));if(!album.isEmpty()||selecting||!query.isEmpty()){ImageButton back=iconButton(R.drawable.ic_chevron_left,"Back",this::back);back.setContentDescription("Back");row.addView(back,new LinearLayout.LayoutParams(dp(44),dp(44)));}
        title=text("",34,fg(),true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(title,new LinearLayout.LayoutParams(0,-1,1));
        ImageButton search=iconButton(R.drawable.ic_search,"Search media",this::searchDialog);search.setContentDescription("Search media");row.addView(search,new LinearLayout.LayoutParams(dp(44),dp(44)));ImageButton menu=iconButton(R.drawable.ic_more_horizontal,"Settings and actions",this::menu);menu.setContentDescription("Settings and actions");LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(dp(44),dp(44));mp.leftMargin=dp(5);row.addView(menu,mp);
        LinearLayout sub=horizontal();header.addView(sub,new LinearLayout.LayoutParams(-1,dp(29)));subtitle=text("",11,muted(),false);subtitle.setSingleLine(true);subtitle.setEllipsize(android.text.TextUtils.TruncateAt.END);sub.addView(subtitle,new LinearLayout.LayoutParams(0,-1,1));
        previous=iconButton(R.drawable.ic_chevron_left,"Previous batch",()->gallery.movePage(-1));previous.setContentDescription("Previous media batch");previous.setPadding(dp(5),dp(4),dp(5),dp(4));sub.addView(previous,new LinearLayout.LayoutParams(dp(32),dp(29)));pager=text("",11,fg(),true);pager.setGravity(Gravity.CENTER);sub.addView(pager,new LinearLayout.LayoutParams(dp(47),-1));next=iconButton(R.drawable.ic_chevron_right,"Next batch",()->gallery.movePage(1));next.setContentDescription("Next media batch");next.setPadding(dp(5),dp(4),dp(5),dp(4));sub.addView(next,new LinearLayout.LayoutParams(dp(32),dp(29)));updateHeader();
    }
    private void updateHeader(){if(title==null)return;title.setText(selecting?selected.size()+" selected":!album.isEmpty()?album:!query.isEmpty()?"Search":tabs[tab]);title.setTextSize(selecting?25:34);subtitle.setText(!query.isEmpty()?query+" · "+shown.size()+" items":collectionMode?"Your collections":!hasAccess()?"Allow access to photos and videos":!loaded?"Loading your library…":shown.size()+" media items");page(gallery.pageIndex(),gallery.pageCount());}
    private void buildNav(){navButtons.removeAllViews();String[] labels=selecting?new String[]{"Select all","Favourite","Done"}:tabs;for(int i=0;i<labels.length;i++){final int n=i;LinearLayout item=vertical();item.setGravity(Gravity.CENTER);item.setContentDescription(labels[i]);item.setFocusable(true);item.setClickable(true);item.setOnClickListener(v->{if(selecting){if(n==0){for(Media m:shown)selected.add(m.uri.toString());gallery.marks(favorites,selected,true);updateHeader();}else if(n==1){favorites.addAll(selected);saveFavorites();finishSelection();}else finishSelection();}else switchTab(n);});ImageView icon=new ImageView(this);icon.setImageDrawable(vector(selecting?new int[]{R.drawable.ic_check_square,R.drawable.ic_heart,R.drawable.ic_check}[i]:new int[]{R.drawable.ic_image,R.drawable.ic_folder,R.drawable.ic_film,R.drawable.ic_heart}[i],23));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);item.addView(icon,new LinearLayout.LayoutParams(dp(23),dp(23)));TextView label=text(labels[i],10,fg(),i==tab);label.setGravity(Gravity.CENTER);label.setIncludeFontPadding(false);label.setSingleLine(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(18));lp.topMargin=dp(3);item.addView(label,lp);navButtons.addView(item,new LinearLayout.LayoutParams(0,-1,1));}markTabs(false);}
    private void markTabs(boolean animate){glass.tab(selecting?0:tab,selecting?3:4);for(int i=0;i<navButtons.getChildCount();i++){View item=navButtons.getChildAt(i);boolean active=selecting||i==tab;item.setAlpha(active?1f:.65f);item.setSelected(active);if(animate&&active&&motion&&ValueAnimator.areAnimatorsEnabled()){View icon=((LinearLayout)item).getChildAt(0);icon.animate().cancel();icon.setScaleX(.86f);icon.setScaleY(.86f);icon.animate().scaleX(1).scaleY(1).setDuration(400).setInterpolator(new android.view.animation.OvershootInterpolator(2f)).start();}}}
    private String stateKey(){return layoutMode+":"+tab+":"+album+":"+query;}
    private void remember(){if(!collectionMode&&gallery!=null)positions.put(stateKey(),new float[]{gallery.pageIndex(),gallery.scrollPosition()});}
    private boolean isCollections(){return (tab==1||tab==2)&&album.isEmpty()&&query.isEmpty();}
    private void switchTab(int i){if(i==tab&&album.isEmpty()&&query.isEmpty())return;remember();tab=i;album="";query="";buildHeader();markTabs(true);render(true);}
    private List<Media> filtered(){ArrayList<Media> list=new ArrayList<>();String q=query.toLowerCase(Locale.ROOT);for(Media m:all){if(tab==3&&!favorites.contains(m.uri.toString()))continue;if(!album.isEmpty()&&!m.album.equals(album))continue;if(!q.isEmpty()&&!(m.name+" "+m.album+" "+m.day+" "+m.displayDate("MMMM yyyy")).toLowerCase(Locale.ROOT).contains(q))continue;list.add(m);}if(layoutMode==2)list.sort(Comparator.comparing((Media m)->m.name,String.CASE_INSENSITIVE_ORDER).thenComparing(m->m.uri.toString()));return list;}
    private void render(boolean animate){shown=filtered();boolean was=collectionMode;collectionMode=isCollections();if(collectionMode){ScrollView old=collections;buildCollections(animate);glass.source(collections);if(old!=null){old.setEnabled(false);if(animate&&motion&&ValueAnimator.areAnimatorsEnabled())old.animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(230).withEndAction(()->content.removeView(old)).start();else content.removeView(old);}gallery.animate().cancel();if(animate&&motion&&ValueAnimator.areAnimatorsEnabled()&&gallery.getVisibility()==View.VISIBLE)gallery.animate().alpha(0).setDuration(230).withEndAction(()->{if(collectionMode){gallery.setVisibility(View.INVISIBLE);gallery.setAlpha(1);}}).start();else gallery.setVisibility(View.INVISIBLE);glass.invalidate();}else{
            ScrollView old=collections;collections=null;glass.source(null);gallery.animate().cancel();gallery.setAlpha(1);gallery.setVisibility(View.VISIBLE);gallery.marks(favorites,selected,selecting);gallery.grouping(layoutMode==0);gallery.setMedia(shown,animate&&!was);float[] pos=positions.get(stateKey());if(pos!=null)gallery.restore((int)pos[0],pos[1]);if(animate&&was)gallery.replay();if(old!=null){old.setClickable(false);if(animate&&motion&&ValueAnimator.areAnimatorsEnabled())old.animate().alpha(0).scaleX(.96f).scaleY(.96f).setDuration(230).withEndAction(()->content.removeView(old)).start();else content.removeView(old);}}
        updateHeader();if(animate&&motion&&ValueAnimator.areAnimatorsEnabled()){title.animate().cancel();title.setAlpha(0);title.setTranslationY(dp(8));title.animate().alpha(1).translationY(0).setDuration(280).start();}}
    private void buildCollections(boolean animate){collections=new ScrollView(this);collections.setFillViewport(false);collections.setVerticalScrollBarEnabled(false);collections.setOnScrollChangeListener((v,x,y,ox,oy)->glass.invalidate());collections.setClipToPadding(false);LinearLayout list=vertical();list.setPadding(dp(20),dp(8),dp(20),dp(110));collections.addView(list,new ScrollView.LayoutParams(-1,-2));content.addView(collections,frame(-1,-1,Gravity.TOP));LinkedHashMap<String,List<Media>> groups=new LinkedHashMap<>();for(Media m:all)groups.computeIfAbsent(m.album,k->new ArrayList<>()).add(m);
        if(tab==2){LinkedHashMap<String,List<Media>> days=new LinkedHashMap<>();for(Media m:all)days.computeIfAbsent(m.day,k->new ArrayList<>()).add(m);int i=0;for(List<Media> media:days.values()){if(i>=40)break;Media cover=media.get(0);LinearLayout card=collectionCard(cover,cover.displayDate("d MMMM yyyy"),media.size()+" memories",()->{remember();query=cover.day;buildHeader();render(true);},true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(16);list.addView(card,lp);animateCard(card,i++,animate);}}
        else{LinearLayout row=null;int i=0;for(Map.Entry<String,List<Media>> entry:groups.entrySet()){String name=entry.getKey();if(i%2==0){row=horizontal();row.setGravity(Gravity.TOP);list.addView(row,new LinearLayout.LayoutParams(-1,-2));}LinearLayout card=collectionCard(entry.getValue().get(0),name,entry.getValue().size()+" items",()->{remember();album=name;buildHeader();render(true);},false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(4),0,dp(4),dp(19));row.addView(card,lp);animateCard(card,i++,animate);}if(i%2==1&&row!=null)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
        if(list.getChildCount()==0){TextView t=text("No media available. Allow access from the menu.",14,muted(),false);list.addView(t);}}
    private LinearLayout collectionCard(Media cover,String label,String count,Runnable action,boolean story){LinearLayout card=vertical();card.setClickable(true);card.setFocusable(true);card.setContentDescription(label+", "+count);card.setOnClickListener(v->action.run());ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setBackground(round(0xff35373a,24,0));im.setClipToOutline(true);card.addView(im,new LinearLayout.LayoutParams(-1,dp(story?205:145)));Runnable update=()->handler.post(()->{if(!isDestroyed()){Bitmap b=thumbs.get(cover,()->{});if(b!=null)im.setImageBitmap(b);}});Bitmap b=thumbs.get(cover,update);if(b!=null)im.setImageBitmap(b);TextView t=text(label,16,fg(),true);t.setSingleLine(true);t.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(27));lp.topMargin=dp(6);card.addView(t,lp);card.addView(text(count,12,muted(),false),new LinearLayout.LayoutParams(-1,dp(20)));return card;}
    private void animateCard(View card,int i,boolean animate){if(!animate||!motion||!ValueAnimator.areAnimatorsEnabled())return;card.setAlpha(0);card.setScaleX(.78f);card.setScaleY(.78f);card.setTranslationY(dp(16));card.animate().alpha(1).scaleX(1).scaleY(1).translationY(0).setStartDelay(Math.min(330,(long)(i*stagger))).setDuration((long)duration).setInterpolator(new android.view.animation.OvershootInterpolator(.95f)).start();}
    @Override public void date(String s){if(layoutMode==0&&subtitle!=null&&!collectionMode&&!selecting&&query.isEmpty()&&!s.contentEquals(subtitle.getText()))subtitle.setText(s);}
    @Override public void page(int i,int count){if(pager==null)return;int visibility=!collectionMode&&count>1?View.VISIBLE:View.GONE;pager.setVisibility(visibility);previous.setVisibility(visibility);next.setVisibility(visibility);pager.setText((i+1)+" / "+count);previous.setEnabled(i>0);next.setEnabled(i+1<count);previous.setAlpha(i>0?1f:.3f);next.setAlpha(i+1<count?1f:.3f);}
    @Override public void redrawGlass(){if(glass!=null)glass.invalidate();}
    @Override public void open(Media m){if(selecting){toggle(m);return;}showViewer(m);}
    @Override public void hold(Media m){if(!selecting){selecting=true;selected.clear();buildNav();}toggle(m);}
    private void toggle(Media m){String key=m.uri.toString();if(!selected.add(key))selected.remove(key);gallery.marks(favorites,selected,true);updateHeader();}
    private void finishSelection(){selecting=false;selected.clear();remember();buildNav();buildHeader();render(false);}
    private void saveFavorites(){prefs.edit().putStringSet("favorites",new HashSet<>(favorites)).apply();}
    private GlassDialog dialog(String title){return new GlassDialog(this, title,light,motion);}
    private void searchDialog(){GlassDialog d=dialog("Search media");EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(fg());input.setHintTextColor(muted());input.setHint("Filename, album or date");input.setText(query);input.setPadding(dp(16),dp(12),dp(16),dp(12));input.setBackground(round(light?0x10000000:0x18ffffff,17,light?0x22000000:0x35ffffff));d.body.addView(input,new LinearLayout.LayoutParams(-1,-2));d.buttons("Cancel",null,"Search",()->{remember();query=input.getText().toString().trim();album="";buildHeader();render(true);});d.show();}
    private void menu(){GlassDialog d=dialog("Hive Gallery");String[] options={light?"Dark mode":"Light mode","Motion & appearance","Replay entry animation","Manage photo access","Accessible media list","About Hive","Gallery layout"};int[] icons={R.drawable.ic_sun,R.drawable.ic_sliders,R.drawable.ic_play,R.drawable.ic_image,R.drawable.ic_grid,R.drawable.ic_info,R.drawable.ic_folder};for(int i=0;i<options.length;i++){final int n=i;d.option(icons[i],options[i],null,false,()->{d.dismiss();switch(n){case 0:light=!light;prefs.edit().putBoolean("light",light).apply();remember();applyTheme();buildHeader();buildNav();render(false);break;case 1:settings();break;case 2:if(collectionMode){remember();render(true);}else gallery.replay();break;case 3:requestMedia();break;case 4:accessibleList();break;case 5:GlassDialog about=dialog("Hive Gallery "+BuildConfig.VERSION_NAME);about.message("Native honeycomb gallery. Photos stay on your device.\n\nBuild "+BuildConfig.VERSION_CODE);about.buttons(null,null,"Done",null);about.show();break;case 6:layoutDialog();break;}});}d.buttons(null,null,"Close",null);d.show();}
    private void layoutDialog(){GlassDialog d=dialog("Gallery layout");String[] names={"Chronological","Continuous honeycomb","Continuous A–Z"},desc={"Day, month and year sections","Newest first, no date sections","Filename order, no date sorting"};for(int i=0;i<names.length;i++){final int n=i;d.option(R.drawable.ic_grid,names[i],desc[i],i==layoutMode,()->{d.dismiss();if(n!=layoutMode){remember();layoutMode=n;prefs.edit().putInt("layout_mode",n).apply();render(true);}});}d.buttons(null,null,"Cancel",null);d.show();}
