        viewerPrev.setEnabled(viewIndex>0);viewerPrev.setAlpha(viewIndex>0?1:.3f);viewerNext.setEnabled(viewIndex<viewList.size()-1);viewerNext.setAlpha(viewIndex<viewList.size()-1?1:.3f);
