        for(int i=start;i<end;i++){final int idx=i;Media q=viewList.get(i);ImageView mini=new ImageView(this);mini.setScaleType(ImageView.ScaleType.CENTER_CROP);mini.setBackground(round(0xff35373a,6,i==viewIndex?fg():0));mini.setClipToOutline(true);mini.setAlpha(i==viewIndex?1:.55f);mini.setContentDescription(q.name);mini.setOnClickListener(v->requestViewer(idx));int available=Math.max(180,(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density)-24);int miniWidth=Math.min(34,Math.max(22,(available-28-13)/7));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(i==viewIndex?miniWidth+13:miniWidth),dp(i==viewIndex?52:42));lp.setMargins(dp(2),0,dp(2),0);viewerFilm.addView(mini,lp);Runnable callback=()->{if(mini.getParent()==viewerFilm){Bitmap th=thumbs.peek(q);if(th!=null)mini.setImageBitmap(th);}};Bitmap th=thumbs.get(q,callback);if(th!=null)mini.setImageBitmap(th);}
