    private void details(Media m){GlassDialog d=dialog("Media details");d.message(m.name);d.field("Captured",m.displayDate("d MMMM yyyy, HH:mm"));d.field("Album",m.album);d.field("Type",m.video?"Video":"Photo");if(m.video)d.field("Duration",String.format(Locale.US,"%d:%02d",m.duration/60000,(m.duration/1000)%60));d.buttons(null,null,"Done",null);d.show();}
